VZ.live('dpMS',{rng:[['dpMSg','g']],seg:[['dpMSm','m','semi']]},st=>{const g=st.g||0,m=st.m||'semi';
 const TOP=60,BOT=380,yL=290,yH=150,yM=(yL+yH)/2;
 let bands=[];
 if(g===0)bands=[[yH,1]];
 else if(m==='semi'){const hyb=2/Math.pow(2,g);bands=[[yM,hyb],[yL,1-hyb]]}
 else if(m==='cons'){const heavy=1/Math.pow(2,g);bands=[[yH,heavy],[yL,1-heavy]]}
 else{const f=1/Math.pow(2,g);bands=[[yL-(yL-yH)*f,1]]}
 let h=`<rect x="420" y="${TOP}" width="160" height="${BOT-TOP}" rx="30" fill="#f4f5fa" stroke="#6b7086" stroke-width="3"/>`;
 h+=t(600,yH+6,'тяжёлая ¹⁵N/¹⁵N',{s:16,w:600,c:C.muted})+t(600,yM+6,'гибридная ¹⁵N/¹⁴N',{s:16,w:600,c:C.muted})+t(600,yL+6,'лёгкая ¹⁴N/¹⁴N',{s:16,w:600,c:C.muted});
 [yH,yM,yL].forEach(y=>{h+=ln(585,y,598,y,{c:C.muted,w:1.5})});
 bands.forEach(([y,f])=>{if(f>0.001)h+=rect(430,y-6,140,12,'#2d2f55',{r:5,op:Math.max(.18,Math.min(1,f*1.3))})+t(400,y+6,Math.round(f*100)+'%',{s:16,w:700,a:'end'})});
 h+=t(40,60,'поколение на ¹⁴N: '+g,{s:20,w:800})+t(40,90,'градиент CsCl, равновесное центрифугирование',{s:15,c:C.muted});
 const M={semi:'Полуконсервативная (так и есть)',cons:'Консервативная (отвергнута)',disp:'Дисперсная (отвергнута)'}[m];
 const D2={semi:'Каждая дочерняя молекула получает одну старую цепь. Гибридных молекул всегда 2 на каждую исходную, поэтому их доля 2/2ⁿ, а остальные лёгкие.',cons:'Старая двойная спираль остаётся целой: тяжёлая полоса сохраняется, лёгкая растёт. Уже после первого деления видно две полосы, а в опыте была одна.',disp:'Старые и новые куски перемешаны в каждой цепи: всегда одна полоса, которая с каждым поколением смещается к лёгкой. После первого деления неотличима от полуконсервативной, а после второго в опыте полос стало две.'}[m];
 return {svg:h,tx:`<b>${M}</b>${D2}`}});

VZ.live('dpFlow',{seg:[['dpFlowS','k','ctrl']]},st=>{const k=st.k||'ctrl';
 const P={ctrl:{g1:.55,s:.25,g2:.20,sub:0,p8:0,n:'Контроль (растущая культура)',d:'55% клеток в пике 2c (G1 и G0), 25% между пиками (S), 20% в пике 4c (G2 и M). При цикле 20 ч: G1 около 11 ч, S около 5 ч, G2 + M около 4 ч (без поправки на то, что молодых клеток в растущей культуре больше).'},
  col:{g1:.18,s:.12,g2:.70,sub:0,p8:0,n:'16 ч с колхицином',d:'Веретено не собирается, клетки копятся в митозе: растёт пик 4c. Отличить G2 от M по окраске ДНК нельзя; помогают митотический индекс под микроскопом или антитела к фосфорилированному гистону H3 (метка только митоза).'},
  gf:{g1:.90,s:.04,g2:.06,sub:0,p8:0,n:'16 ч без фактора роста',d:'Клетки не проходят точку рестрикции в G1, а те, что уже были в S и G2, заканчивают цикл и тоже останавливаются в G1. Почти все клетки в пике 2c (так же действует контактное торможение).'},
  apo:{g1:.45,s:.15,g2:.12,sub:.28,p8:0,n:'16 ч с веществом, вызывающим апоптоз',d:'Пик левее 2c (sub-G1): ДНК при апоптозе режется, часть фрагментов выходит из фиксированной клетки, окраска слабее.'},
  poly:{g1:.35,s:.15,g2:.30,sub:0,p8:.20,n:'Полиплоидизация',d:'Клетки удвоили ДНК, но не разделились (например, после цитохалазина B или при эндоредупликации): появляется пик 8c.'}}[k];
 const A=axes([110,40,960,320],[0,9],[0,1],{xt:[2,4,8],xf:v=>v+'c',yt:[],xl:'содержание ДНК на клетку (яркость)',yl:'число клеток'});
 const gauss=(x,m,sd)=>Math.exp(-Math.pow((x-m)/sd,2)/2);
 const f=x=>P.g1*gauss(x,2,.18)*2.2+P.g2*gauss(x,4,.3)*1.4+P.s*(x>2.2&&x<3.8?0.42:0)+P.sub*gauss(x,1.1,.4)*.8+P.p8*gauss(x,8,.5)*1.1;
 let mx=0;for(let x=0;x<9;x+=.02)mx=Math.max(mx,f(x));
 const fn=x=>f(x)/mx*0.95;
 let pts=[];for(let x=0.3;x<=9;x+=.03)pts.push([A.sx(x),A.sy(fn(x))]);
 let h=A.h+`<path d="M${A.sx(.3)} ${A.sy(0)} ${pts.map(p=>'L'+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')} L${A.sx(9)} ${A.sy(0)} Z" fill="${C.hema}" opacity=".22"/>`+VZ.path(pts,{c:C.hema,w:3});
 h+=t(A.sx(2),A.sy(fn(2))-12,'G1',{s:16,w:700,a:'middle'})+t(A.sx(3),A.sy(fn(3))-12,'S',{s:16,w:700,a:'middle'})+t(A.sx(4),A.sy(fn(4))-12,'G2+M',{s:16,w:700,a:'middle'});
 if(P.sub)h+=t(A.sx(1.1),A.sy(fn(1.1))-12,'sub-G1',{s:16,w:700,a:'middle',c:C.bad});if(P.p8)h+=t(A.sx(8),A.sy(fn(8))-12,'8c',{s:16,w:700,a:'middle',c:C.violet});
 return {svg:h,tx:`<b>${P.n}</b>${P.d}`}});

